// sunspotd: a resident Sunspot prover. Loads the ACIR, the constraint system and the proving key
// once (the key is gigabytes and takes seconds to read), then proves on request over stdin/stdout,
// one JSON object per line. Logs go to stderr. Generated by circuit/scripts/sunspot-install.sh.
//
//	sunspotd --acir circuit.json --pk circuit.pk [--ccs circuit.ccs] [--work /dev/shm]
//
// --ccs names the constraint system: read when the file exists, otherwise compiled from the ACIR
// (deterministic, ~15 s for this circuit) and written there for the next start. Name it after the
// ACIR's hash so a changed circuit misses the cache. Without --ccs it is compiled and not kept.
//
// Startup prints {"ready":true,"constraints":N,"publicInputs":N,"loadMs":N,"ccs":"read|compiled|compiled, cached"} on stdout.
// Request:  {"id":"<any>","witness":"<base64 of the gzipped Noir witness stack (nargo execute / noir_js)>"}
// Response: {"id":"<same>","proof":"<base64>","publicWitness":"<base64>","ms":N}
//        or {"id":"<same>","error":"..."}
// Request:  {"id":"<any>","ping":true}  ->  {"id":"<same>","pong":true}
// Requests are served one at a time in order; the caller queues.
package main

import (
	"bufio"
	"bytes"
	"encoding/base64"
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"time"

	"github.com/consensys/gnark-crypto/ecc"
	ecc_bn254 "github.com/consensys/gnark-crypto/ecc/bn254"
	"github.com/consensys/gnark/backend/groth16"
	"github.com/consensys/gnark/constraint"
	gnarklogger "github.com/consensys/gnark/logger"
	"github.com/rs/zerolog"
	"github.com/rs/zerolog/log"

	"github.com/reilabs/sunspot/go/acir"
	"github.com/reilabs/sunspot/go/bn254"
)

type request struct {
	ID      string `json:"id"`
	Witness string `json:"witness,omitempty"`
	Ping    bool   `json:"ping,omitempty"`
}

type response struct {
	ID            string `json:"id"`
	Proof         string `json:"proof,omitempty"`
	PublicWitness string `json:"publicWitness,omitempty"`
	Ms            int64  `json:"ms,omitempty"`
	Pong          bool   `json:"pong,omitempty"`
	Error         string `json:"error,omitempty"`
}

func main() {
	acirPath := flag.String("acir", "", "ACIR JSON (nargo compile, the Noir release Sunspot reads)")
	pkPath := flag.String("pk", "", "Groth16 proving key")
	ccsPath := flag.String("ccs", "", "constraint system (.ccs): read if present, else compiled from the ACIR and written here")
	work := flag.String("work", os.TempDir(), "directory for the per-request witness file (tmpfs preferred)")
	flag.Parse()
	if *acirPath == "" || *pkPath == "" {
		fmt.Fprintln(os.Stderr, "usage: sunspotd --acir <json> --pk <pk> [--ccs <ccs>] [--work <dir>]")
		os.Exit(2)
	}
	// stdout carries only the protocol: our logs and gnark's go to stderr.
	log.Logger = log.Output(zerolog.ConsoleWriter{Out: os.Stderr, TimeFormat: time.RFC3339})
	gnarklogger.Set(zerolog.New(zerolog.ConsoleWriter{Out: os.Stderr, TimeFormat: time.RFC3339}).With().Timestamp().Logger())

	start := time.Now()
	type E = constraint.U64
	type T = *bn254.BN254Field
	program, err := acir.LoadACIR[T, E](*acirPath)
	if err != nil {
		fatal("load ACIR: %v", err)
	}
	var ccs constraint.ConstraintSystem
	ccsSource := "compiled"
	if f, err := os.Open(*ccsPath); *ccsPath != "" && err == nil {
		ccs = groth16.NewCS(ecc.BN254)
		if _, err := ccs.ReadFrom(bufio.NewReaderSize(f, 1<<24)); err != nil {
			fatal("read CCS %s: %v (delete it to have it recompiled)", *ccsPath, err)
		}
		f.Close()
		ccsSource = "read"
	} else {
		if *ccsPath != "" && !os.IsNotExist(err) {
			fatal("open CCS: %v", err)
		}
		compiled, err := program.Compile()
		if err != nil {
			fatal("compile ACIR: %v", err)
		}
		cs, ok := compiled.(constraint.ConstraintSystem)
		if !ok {
			fatal("compiled constraint system has an unexpected type")
		}
		ccs = cs
		if *ccsPath != "" {
			// Written beside its final name and renamed, so a start interrupted mid-write leaves
			// no half file to be read next time.
			if err := writeCCS(ccs, *ccsPath); err != nil {
				log.Warn().Err(err).Str("path", *ccsPath).Msg("could not cache the constraint system")
			} else {
				ccsSource = "compiled, cached"
			}
		}
	}
	log.Info().Str("ccs", ccsSource).Dur("took", time.Since(start)).Msg("constraint system ready")
	pkFile, err := os.Open(*pkPath)
	if err != nil {
		fatal("open proving key: %v", err)
	}
	pk := groth16.NewProvingKey(ecc.BN254)
	if _, err := pk.ReadFrom(bufio.NewReaderSize(pkFile, 1<<24)); err != nil {
		fatal("read proving key: %v", err)
	}
	pkFile.Close()
	out := bufio.NewWriter(os.Stdout)
	emit := func(v any) {
		b, _ := json.Marshal(v)
		out.Write(b)
		out.WriteByte('\n')
		out.Flush()
	}
	emit(map[string]any{
		"ready": true, "constraints": ccs.GetNbConstraints(), "publicInputs": len(program.PublicWitnesses()),
		"loadMs": time.Since(start).Milliseconds(), "ccs": ccsSource,
	})
	log.Info().Int("constraints", ccs.GetNbConstraints()).Dur("load", time.Since(start)).Msg("sunspotd ready")

	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	var line bytes.Buffer
	for {
		line.Reset()
		for {
			chunk, isPrefix, err := in.ReadLine()
			if err != nil {
				log.Info().Msg("stdin closed, exiting")
				return
			}
			line.Write(chunk)
			if !isPrefix {
				break
			}
		}
		if line.Len() == 0 {
			continue
		}
		var req request
		if err := json.Unmarshal(line.Bytes(), &req); err != nil {
			emit(response{Error: fmt.Sprintf("bad request: %v", err)})
			continue
		}
		if req.Ping {
			emit(response{ID: req.ID, Pong: true})
			continue
		}
		resp := prove(program, ccs, pk, *work, req)
		emit(resp)
	}
}

type acirProgram = acir.ACIR[*bn254.BN254Field, constraint.U64]

func writeCCS(ccs constraint.ConstraintSystem, path string) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	part := path + ".part"
	f, err := os.Create(part)
	if err != nil {
		return err
	}
	w := bufio.NewWriterSize(f, 1<<24)
	if _, err := ccs.WriteTo(w); err != nil {
		f.Close()
		os.Remove(part)
		return err
	}
	if err := w.Flush(); err != nil {
		f.Close()
		os.Remove(part)
		return err
	}
	if err := f.Close(); err != nil {
		os.Remove(part)
		return err
	}
	return os.Rename(part, path)
}

func prove(program acirProgram, ccs constraint.ConstraintSystem, pk groth16.ProvingKey, work string, req request) response {
	t0 := time.Now()
	raw, err := base64.StdEncoding.DecodeString(req.Witness)
	if err != nil {
		return response{ID: req.ID, Error: fmt.Sprintf("witness is not base64: %v", err)}
	}
	// Sunspot reads the witness stack from a file; keep it on tmpfs and remove it right away.
	f, err := os.CreateTemp(work, "sunspotd-*.gz")
	if err != nil {
		return response{ID: req.ID, Error: fmt.Sprintf("temp file: %v", err)}
	}
	path := f.Name()
	defer os.Remove(path)
	if _, err := f.Write(raw); err != nil {
		f.Close()
		return response{ID: req.ID, Error: fmt.Sprintf("write witness: %v", err)}
	}
	f.Close()
	witness, err := program.GetWitness(path, ecc_bn254.ID.ScalarField())
	if err != nil {
		return response{ID: req.ID, Error: fmt.Sprintf("witness: %v", err)}
	}
	proof, err := groth16.Prove(ccs, pk, witness)
	if err != nil {
		return response{ID: req.ID, Error: fmt.Sprintf("prove: %v", err)}
	}
	var proofBuf, pwBuf bytes.Buffer
	if _, err := proof.WriteRawTo(&proofBuf); err != nil {
		return response{ID: req.ID, Error: fmt.Sprintf("serialize proof: %v", err)}
	}
	pw, err := witness.Public()
	if err != nil {
		return response{ID: req.ID, Error: fmt.Sprintf("public witness: %v", err)}
	}
	if _, err := pw.WriteTo(&pwBuf); err != nil {
		return response{ID: req.ID, Error: fmt.Sprintf("serialize public witness: %v", err)}
	}
	log.Info().Str("id", req.ID).Dur("took", time.Since(t0)).Msg("proved")
	return response{
		ID: req.ID, Proof: base64.StdEncoding.EncodeToString(proofBuf.Bytes()),
		PublicWitness: base64.StdEncoding.EncodeToString(pwBuf.Bytes()), Ms: time.Since(t0).Milliseconds(),
	}
}

func fatal(format string, args ...any) {
	msg := fmt.Sprintf(format, args...)
	log.Error().Msg(msg)
	b, _ := json.Marshal(map[string]any{"ready": false, "error": msg})
	fmt.Println(string(b))
	os.Exit(1)
}

